import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"賁","description":"高島易斷 - 賁","frontmatter":{"title":"賁","description":"高島易斷 - 賁"},"headers":[],"relativePath":"classics/takashima/022.md","filePath":"classics/takashima/022.md"}'),i={name:"classics/takashima/022.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="賁" tabindex="-1">賁 <a class="header-anchor" href="#賁" aria-label="Permalink to “賁”">​</a></h1><h2 id="賁-1" tabindex="-1">賁 <a class="header-anchor" href="#賁-1" aria-label="Permalink to “賁”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>賁：亨，小利有攸往。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《賁》卦上體山，山蘊質素，下體火，火吐文光，下火上燭，則質而有文，故曰《賁》。文質交錯，剛柔得中，故曰“亨”。《離》火之明，遇山而止，則所進者小矣，故曰“小利有攸往”。其義，則《彖》辭詳之矣。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>山下有火，賁，君子以明庶攻，無敢折獄。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>《艮》山之下有《離》火，《艮》，一陽高出二陰之上，陽塞於外而不通，故止；《離》，二陽之中含一陰，是內虛而含明，故明。君子法之，“以明庶政”，“庶政”者，或兼教養，或兼兵食，《洪範》所謂“八政”皆是也。暗則紊，明則治，取之高，而政教明矣。明以致察，過察則失嚴，故於折獄，則曰“無敢”。“無敢”者，謂不敢自用其明也。虛明之心存於中，而慈祥之政行於外，明其所當明，而不敢過用其明，取之於《艮》，明於是乎止焉。豐田“致刑”，以“明而動”，賁曰“無敢”，以明而止。不動則民不畏法，不止則民不聊生，有相濟而行也。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：目下正當發動，百事順適，但上有阻止，未能遂意徑行。</p><p>○　問商業：主經理人才幹強明，足以任事；但精明者必刻利，還宜留意。</p><p>○　問家宅：恐宅中時有火光發動，幸即撲滅，無大害也。</p><p>○　問戰徵：前面有山，未易進攻。</p><p>○　問疾病：是鬱火上蒸之症，宜息火，猶不可過用寒劑，致真火撲滅。</p><p>○　問行人：欲歸又止，尚未定也。</p><p>○　問六甲：生女。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>初剛在下，故曰賁趾，“徒”，徒行也。古者從大夫之後，不可徒行，初無位，故“舍車而徒”。賁趾者，是踐仁履義，以仁義“賁其趾”者也，不以乘車為賁，而以徒行為賁。乘車者，世之所賁，君子所恥，是以舍之。《象傳》曰“義弗乘也”，喜初之能守義也。</p><h2 id="初九佔" tabindex="-1">初九佔 <a class="header-anchor" href="#初九佔" aria-label="Permalink to “初九佔”">​</a></h2><p>○　問時運：生性清高，不合時趨，以德亨，不以名亨。</p><p>○　問商業：必是肩負買賣，非舟車販運之業，雖小亦亨。</p><p>○　問家宅：是勤儉起家，頗有知足不辱之風。</p><p>○　問戰徵：陸軍利。</p><p>○　問行人：中途遇阻，步行而歸。</p><p>○　問疾病：症在初起，不食藥而可愈也。</p><p>○　問訟事：恐有懲役之災。</p><p>○　問失物：已捨去之，尋覓徒勞。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>明治十九年，佔某貴顯氣運，筮得《賁》之《艮》。</p><p>斷曰：此卦上《艮》下《離》，所謂高山仰止者，某貴顯之德望也；所謂高明遍照者，某貴顯之功業也，是當今所共知者也。現時退位閒居，今佔得《賁》初九，曰“賁其趾，舍車而徒”，爻象正合。初爻為無位，陽剛在下，賁，有文也；趾，足也，從止，有退歸之象。“舍車”，猶舍位而隱也，“徒”，行也，將復起也。舍車徒行，是某貴顯將潛行民間，窺察民情風俗，以益光文明之治，補維新以來所未修，是某貴顯之隱衷也，爻象以明示之。在某貴顯為維新元勳，雖暫退間，其心頭豈一日忘天下哉！茲值初爻，賁猶未光，至三而賁盛，至六猶能反其賁，以協於中。賁之運正長，知某貴顯，後日必德望愈隆，功業愈大也。《彖》所謂“觀乎天文，以察時變，觀乎人文，以化成天下”，皆可於某貴顯見之。後果如此佔。今輔佐朝政，望同山斗，遇際明良，是《賁》之所以為《賁》也。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>二以柔居柔，其爻自《噬嗑》六五柔來，變為六二，即《彖傳》所謂“柔來而文剛”也。取象於頤，此爻曰“須”，須，隨頤而動，故注曰：須之為物，上附者也。柔來文剛，文剛者，賁也，故曰“賁其須”。鬚眉為人生之儀表，所謂嚴其瞻視者，此也。《象傳》曰“與上興也”，“上”，謂上卦《噬嗑》，“興”，動也。《噬嗑》內卦為《震》，《震》為動，須附上，爻自《噬嗑》來，故曰“與上興也”。</p><h2 id="六二佔" tabindex="-1">六二佔 <a class="header-anchor" href="#六二佔" aria-label="Permalink to “六二佔”">​</a></h2><p>○　問時運：目下平平，只可依人成事。</p><p>○　問商業：與富商合業，必大興旺，吉。</p><p>○　問戰徵：必須與大軍同進，方可得勝。</p><p>○　問家宅：叨上人之福澤，藉以光大門楣。</p><p>○　問婚嫁：“歸妹以須，”尚宜待也。</p><p>○　問六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>明治十四年四月佔國會。方今我國輿論，鹹願開設國會，群議紛紛，未可臆斷，特佔一卦，得《賁》之《大畜》。</p><p>斷曰：此卦自二至上為五年，其間不見兇咎。《賁》下卦為《剝》，《剝》之上即第六年，其兇尤甚。今審度避凶趨吉之方，須就變卦《大畜》探索。為之先說《賁》終《剝》來之兇象，複述變卦《大畜》之卦義。《彖》辭曰：“賁亨，小利有攸往”。賁者文飾也，凡事飾於外者，必由其內有缺乏也。今當開設國會，各府縣推舉代議士，才力學識，未必完全，多皆徒施外飾而已。《彖傳》曰“柔來而文剛，”剛上而文柔”，謂上卦之柔，來賁下卦之剛，下卦之剛，上賁上卦之柔，上下各以剛柔，互相賁飾，此《彖傳》義也。今擬之國會，上卦為官吏，下卦為代議士，各以論說相抵抗者也。曰“賁亨”，知國會之事無不亨通；曰“小利有攸住”，知國會雖可進行，未免有所退止也；曰“觀乎天文，以察時變”，謂當察時機之會，審宇內之勢，以維持國體於不朽也；曰“觀乎人文，以化成天下”，謂應民心之歸向，文運之昌明，開設國會，上下合志，可以計劃國家之安寧。此就《彖傳》義而釋之如是，進推六爻，初爻“賁其趾”，舍車而徒”。初爻在下，是無位也，謂微賤下民，亦將持杖徒行，奔走而來觀德化也。二爻“賁其須，”《象傳》曰“賁其須，與上興也，”二雖進初一等，其人不能自主，隨人之議論以為議論，如須之隨頤而動也。三爻“賁如濡如，永貞吉，”《象傳》釋之曰：“永貞之吉，終莫之陵也。”三居下卦之上，近比四爻，“賁如濡如”，賁之盛也。三以陽居陽，卦中為主賁，會中為主議，持論不易，能守“永貞”，故吉。《象》謂“終莫之陵”，言無與相抗也。四爻“賁如皤如，白馬翰如，匪寇婚媾”，此爻為政府地位，與三接近。“賁如皤如”者，謂官吏示以從前政府施行之事狀；“白馬翰如”者，謂聽者解得政府之實情；“匪寇婚媾”者，謂感官吏之勤勞，相與輔翼而贊成之也。五爻“賁於丘園”，“束帛戔戔”，謂議士中有知“丘園”之賢士，推薦於朝，當具“束帛”以招之，使之出而共議國是，故“終吉”。上爻“白賁，無咎”，乃退位老臣，謂創興國會，未免近於粉飾，終宜黜華崇實，是返本之道也。從此節財省費，得謀裕國之策也。《賁》之終，《剝》之始也，更論《剝》卦之義。《剝》《彖傳》曰：“剝，剝也，柔變剛也。不利有攸往，小人長也。”“柔變剛”者，是“小人道長”之時也，故曰“不利有攸往”，戒辭也。初爻曰“剝床以足，蔑貞兇，”陰之剝陽，自下而上，邪害正也，謂有武人，惡人民之漸進逼上，欲壓滅其黨類之象。二爻曰“剝床以辨，蔑貞兇”，“辨”者床幹也，指黨類之長，初爻既滅黨類，今又欲殄滅其長之象。三爻曰“剝之無咎”，其黨類為時勢所激，忽起變志，不復顧忌名分，是最不祥之佔也。四爻曰“剝床以膚，兇”，有眾陰逼上之勢，漸逼漸近，其兇更甚。五爻曰“貫魚以宮人寵，無不利”，謂剝之者兇，順之則利，有一時委曲保全之象。上爻曰“碩果不食。君子得輿，小人剝廬”，謂雖當剝極，必有碩果之僅存者，君子處之，謂終得愛戴，小人處之，謂無所容身，是小人慾剝君子，自己亦罹其災之謂也。以上自《賁》移《剝》之卦象也。賁為文明而止之卦，方今人情，徒慕歐英文化，不察時勢之可否，難免剝落之災，如《剝》卦所述，故君子必貴思患而預防也。今佔得《賁》之《大畜》，再釋《大畜》之義，以示佔者。《大畜》《彖傳》曰：“大畜，剛健，篤實，輝光，日新其德。剛上而尚賢，能止健，大正也。不家食吉，養賢也。利涉大川，應乎天也。”《大畜》者，畜之大者也，專在尚賓養賢，以為國家用，足以黼黻太平也。初爻曰“有厲利己”，《象傳》曰：“有厲利己，不犯災也。”初以四為正應，欲進而四畜之，即為艮所抑，有不能達志之象。二爻曰“輿脫輹”，《象傳》曰：“輿脫輹，中無憂也。”二爻見初三兩爻之止，有同願屈抑之象。三爻曰：“良馬逐，利艱貞，日閒輿衛，利有攸往。”《象傳》曰：“利有攸往，上合志也。”三爻以剛健之才，欲銳進而從事者也，為四畜之，使不得進，遂變其志向，謀開墾牧畜等事。曰“良馬逐”，曰“利艱貞”，皆開拓牧畜之象。又曰“閒輿衛”，曰“利有攸往”，並習練軍事之象。如是有益政府，故謂之“上合志也”。四爻曰“童牛之牿，元吉”，《象傳》曰：“六四元吉，有喜也。”此爻當縣官地位，縣官能使無產士族，從事牧畜開墾等事，猶牧童牛，易畜易制之謂也。五爻曰“豶豕之牙，吉”，《象傳》曰：“六五之吉，有慶也。”此爻亦與六四同。上九曰“荷天之衢，亨”，《象傳》曰“荷天之衢，道大行也”，謂全國士民各得其所，天下泰平之象也。以上國會之占斷如此。至翌年七月，政府頒示實施政令三條：一發布明治二十三年開設國會之令；一為救濟無資士族，與以八十萬元之授產金；一政府銳意開造鐵路，計劃中山道及奧羽之佈設，與以年八朱之利息保護。皆呈象於《大畜》之爻義，得時勢之宜者也。《易》象之靈妙如此。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>三以一剛介二陰之間，當賁之盛，“賁如濡如，”潤澤之象。顧陰能賁人，亦能溺人，誡之以“永貞”，在我有常貞之操，斯彼無凌逼之嫌，故曰“吉”。《象傳》曰“永貞之吉，終莫之凌也”，“終”字與“永”字相應，蓋貞而不永，則非有終者也。謂我剛正而永貞，彼自不能凌侮也。</p><h2 id="九三佔" tabindex="-1">九三佔 <a class="header-anchor" href="#九三佔" aria-label="Permalink to “九三佔”">​</a></h2><p>○　問時運：當此盛運，光華潤澤，名利雙收，大亨。</p><p>○　問商業：財源如水，大得清潤，基業亦可保長久，大吉。</p><p>○　問家宅：屋宇華潔，又得流水掩映，可以久居，吉。</p><p>○　問戰徵：一軍皆感被德澤，歡洽同心，可稱王師無敵。</p><p>○　問訟事：得直，彼亦不敢復犯。</p><p>○　問婚嫁：百年偕老，吉。</p><p>○　問六甲：生男。</p><p>○　問行人：衣錦榮耀而歸。</p><p>○　問失物：向水中尋之，得。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>友人某來，請佔氣運，筮得《賁》之《頤》。</p><p>斷曰：此卦一陽居二陰之中，如物入水中，沾濡潤澤，光彩益章，故曰“賁如濡如”，賁之盛也。然賁飾過甚，外耀有餘，往往內美不足，是賁之流弊也。今我國自維新以來，仕途一變，每多有自炫才華，以冀仕進，飾智驚愚，互相標榜，大都如斯。迨一旦得位，毫無寸能，此輩純盜虛聲者，固可暫而不可“永貞”者也，吉何有焉？足下有意當世，宜踐實德，毋博虛名，持之以“貞”，守之以“永”，終得吉也。《象傳》曰：“終莫之凌”。謂賁非虛賁，人復誰能相抗也。足下其留意焉！</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>四在上卦之下，《賁》已過中。“皤”，素白色也，“翰”，白色馬也。卦體三、四、五互《震》，《震》為白馬，故取白馬之象。《震》上六曰“婚媾”，故亦有婚媾之象。四與初為正應，為三所隔，不獲相賁，故曰“皤如”，“白馬翰如”，亦未獲其賁也。然九三剛正，“非寇”，乃求婚媾耳。四與初正應，必相親賁，不能終隔也。《象傳》曰“當位疑”，四疑二也。曰“終無尤”，謂初四正應。終必相合，故云“終無尤”也。</p><h2 id="六四佔" tabindex="-1">六四佔 <a class="header-anchor" href="#六四佔" aria-label="Permalink to “六四佔”">​</a></h2><p>○　問時運：目下運有阻礙，安分則吉，明年便可亨通。</p><p>○　問商業：宜迅疾販售，遲緩，防貨物變色。</p><p>○　問家宅：一宅之內，既有喪事，又逢婚事，前塞後通，無咎。</p><p>○　問戰徵：有和親通好之議。</p><p>○　問疾病：中胸有阻，故上下不調，積阻消化，便無咎也。</p><p>○　同行人：有愛女眷戀，一時未歸。</p><p>○　問六甲：生女。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>有人來，請佔某縉紳氣運，筮得《賁》之《離》。</p><p>斷曰：四以陰居陰，與初為正應，為中間三爻所隔，不獲相賁相親，《象傳》曰“當位疑也”。今佔得四爻，知某縉紳在局，或亦因中有間阻，致生疑慮之處，然其中乘馬翰如而來者，實欲相與親密，並無他意。四爻初則疑之為寇，為將攘奪我利也，至後漸知其真，疑念始解，故曰“匪寇婚媾”。當時某縉紳確有是事，初疑後解，兩情甚洽，果如此佔。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>“丘園”者，園之依丘陵者。艮有丘之象，“賁於丘園”者，謂留意於農桑之事。“束帛”者，贈人之物，“戔戔”者，淺少之意。不賁市朝而賁丘園，敦本也。“束帛戔戔”，謂六五以柔居尊位，能修柔中之德，黜祛奢華，敦崇儉約，如大禹之卑宮室，菲飲食也，故曰“賁於丘園，束帛戔戔”。“吝”，謂居尊位，而留心鄙事，未免吝也，然不失黜華崇實之旨，故曰“終吉”。《象傳》曰“有喜也”，有喜者，謂實有可喜也。天下之俗成於儉，敗於奢，一人倡之，世風可返於淳樸，則所喜非在一人，喜其能移風易俗也。一說，丘園為隱士所居，六五能以“束帛”，聘求丘園之遺賢，共輔文明之治。聘賢僅以“戔戔”束帛，禮意未隆，故曰“吝”；在賢者不以幣帛為悅，而以恭敬為悅，是以幣帛雖微，賢者亦應聘而來，故終有吉也。亦通。</p><h2 id="六五佔" tabindex="-1">六五佔 <a class="header-anchor" href="#六五佔" aria-label="Permalink to “六五佔”">​</a></h2><p>○　問時運：目下恰行正運，然作事一宜儉勤為吉。</p><p>○　問商業：買賣最直木材綢物二行，貨物不必多，而獲利頗佳。</p><p>○　問家宅：農桑為業，勤儉家風，吉。</p><p>○　問戰徵：宜招用野老，以作嚮導，可以得勝。</p><p>○　問婚嫁：聘禮雖微，卻好得一賢婦，大喜。</p><p>○　問六甲：生男。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>友人來，請佔氣運，筮得《賁》之《家人》。</p><p>斷曰：此爻為五居尊位，崇尚儉德，將率天下而從儉也，故不賁宮殿，而賁丘園。“束帛”之禮，以誠相將，不尚豐厚。今佔得此爻，知足下自幼從事商業，一番辛勤，得有今日，資產豐裕，亦足自樂。近來商業，多習歐美之風，全以欺詐為術，華麗自誇，反以曩時樸素敦厚為可吝也。在吾輩敦尚古風者，不屑與之較也，足下惟當安閒，覓一山林佳處，修築園榭，栽植花木，以娛心目，為作養老之計也。人或以吾輩不事世事為吝，然以此而娛老，以此而傳後，終得吉也，謂之“賁於丘園，束帛戔戔，吝，終吉”也。友人從此佔，亦足自樂。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>上處《賁》之終，終極不變，弊將無質，故《賁》之義，始因天下之質，飾之以文，並將天下之文，歸之於質。“白賁”者，素樸自然，是無色也，如寶玉不雕，珍珠不飾，不使文掩其質，“白賁”之謂也。《象傳》曰“上得志也”，居卦之上，處事之外，矯世俗之文飾，而敦尚樸素，獨行其專，優遊自得耳。凡卦如《泰》與《否》、《剝》與《復》、《渙》與《萃》等，皆有對偶，惟《賁》無對，獨於卦中，分賁與不賁兩義為對。是讀《易》之訣也。《中孚》一卦亦然。</p><h2 id="上九佔" tabindex="-1">上九佔 <a class="header-anchor" href="#上九佔" aria-label="Permalink to “上九佔”">​</a></h2><p>○　問時運：好運已終，勞者宜歸於逸，動者宜返於靜，優遊自適，聊以取樂耳。</p><p>○　問商業：現在貨價已高，時令將完，不必裝飾，即可出售，定得利也。</p><p>○　問家宅：清白家風，位置亦高，吉。</p><p>○　問戰徵：身當上將，堂堂之陣，正正之旗，不用譎計奇謀，自然獲勝。吉。</p><p>○　問疾病：病在上焦，宜用清淡之劑，吉。</p><p>○　問行人：得利歸來。</p><p>○　問六甲：生男。</p><p>○　問失物：向高處尋覓，可得。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>維新之際，浦賀管署吏員下村三郎左衛門，舊佐賀藩之士也，罹病日久，來橫就醫。醫曰：病似輕而實重，非滯留受治，恐至危殆。下村氏告於長官，許以留醫。下村氏不以病為慮，強還任地，長官謂餘曰：下村氏之疾如何？子試筮之。筮得《賁》之《明夷》。</p><p>斷回：下村氏必死。長官曰：醫亦視為重症，但子何以豫言其死也？餘曰：《賁》者上山下火，今山變而為地，是《離》明沒於《坤》地之象。上九陽變而為陰，陽者生也，陰者死也，即生變為死之象。又上九之爻辭曰“白賁”，白者喪服也，其死不免矣。後未一月，果接其訃音。</p>',98)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
